CREATE TYPE "MoneyAccountType" AS ENUM ('BANK','CASH','PETTY_CASH'); CREATE TYPE "ChequeStatus" AS ENUM ('ISSUED','RECEIVED','DEPOSITED','CLEARED','BOUNCED','CANCELLED'); CREATE TYPE "LoanStatus" AS ENUM ('ACTIVE','PAID_OFF','CANCELLED');
CREATE TABLE "money_accounts" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID,"type" "MoneyAccountType" NOT NULL,"name" VARCHAR(160) NOT NULL,"ledgerAccountId" UUID NOT NULL,"bankName" VARCHAR(160),"accountNumberMasked" VARCHAR(40),"ifsc" VARCHAR(20),"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("companyId","id"),UNIQUE("companyId","ledgerAccountId"));
CREATE TABLE "money_transfers" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"sourceAccountId" UUID NOT NULL,"destinationAccountId" UUID NOT NULL,"amount" DECIMAL(18,2) NOT NULL CHECK ("amount">0),"transferDate" DATE NOT NULL,"idempotencyKey" VARCHAR(160) NOT NULL,"journalEntryId" UUID NOT NULL,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ("sourceAccountId"<>"destinationAccountId"),UNIQUE("companyId","idempotencyKey"),UNIQUE("companyId","journalEntryId"));
CREATE TABLE "cheques" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"moneyAccountId" UUID NOT NULL,"chequeNumber" VARCHAR(80) NOT NULL,"chequeDate" DATE NOT NULL,"partyName" VARCHAR(240) NOT NULL,"status" "ChequeStatus" NOT NULL,"clearedDate" DATE,"reference" VARCHAR(160),"journalEntryId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("companyId","moneyAccountId","chequeNumber"));
CREATE TABLE "owner_financial_accounts" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"userId" UUID NOT NULL,"capitalLedgerId" UUID NOT NULL,"drawingsLedgerId" UUID NOT NULL,"loanLedgerId" UUID NOT NULL,UNIQUE("companyId","userId"));
CREATE TABLE "loans" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"lender" VARCHAR(240) NOT NULL,"loanType" VARCHAR(80) NOT NULL,"principal" DECIMAL(18,2) NOT NULL,"interestRate" DECIMAL(7,4),"startDate" DATE NOT NULL,"maturityDate" DATE,"liabilityLedgerId" UUID NOT NULL,"moneyAccountId" UUID NOT NULL,"status" "LoanStatus" NOT NULL DEFAULT 'ACTIVE',"reference" VARCHAR(160),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("companyId","id"));
CREATE TABLE "loan_payments" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"loanId" UUID NOT NULL,"moneyAccountId" UUID NOT NULL,"paymentDate" DATE NOT NULL,"principal" DECIMAL(18,2) NOT NULL,"interest" DECIMAL(18,2) NOT NULL,"charges" DECIMAL(18,2) NOT NULL DEFAULT 0,"idempotencyKey" VARCHAR(160) NOT NULL,"journalEntryId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("companyId","idempotencyKey"),UNIQUE("companyId","journalEntryId"));
ALTER TABLE "account_settlements" ADD COLUMN "moneyAccountId" UUID; ALTER TABLE "money_accounts" ADD CONSTRAINT "money_ledger_company_fkey" FOREIGN KEY ("companyId","ledgerAccountId") REFERENCES "ledger_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "money_transfers" ADD CONSTRAINT "transfer_source_company_fkey" FOREIGN KEY ("companyId","sourceAccountId") REFERENCES "money_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "money_transfers" ADD CONSTRAINT "transfer_destination_company_fkey" FOREIGN KEY ("companyId","destinationAccountId") REFERENCES "money_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "loan_payments" ADD CONSTRAINT "payment_loan_company_fkey" FOREIGN KEY ("companyId","loanId") REFERENCES "loans"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "expense_transactions" ADD CONSTRAINT "expense_money_company_fkey" FOREIGN KEY ("companyId","moneyAccountId") REFERENCES "money_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "account_settlements" ADD CONSTRAINT "settlement_money_company_fkey" FOREIGN KEY ("companyId","moneyAccountId") REFERENCES "money_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
